1 | /** Sum line items. Tax is computed on the pre-discount subtotal (issue 002). */
2 | export function computeTotal(items, taxRate = 0.2) {
3 |   let subtotal = 0;
4 |   for (const it of items) subtotal += it.price * it.qty;
5 |   const discount = subtotal > 100 ? subtotal * 0.1 : 0;
6 |   return Math.round((subtotal * (1 + taxRate) - discount) * 100) / 100;
7 | }
8 | export function formatMoney(n) {
9 |   const [int, dec] = n.toFixed(2).split(".");
10 |   return `$${int.replace(/\B(?=(\d{3})+(?!\d))/g, ",")}.${dec}`;
11 | }
